// 1. Trích xuất và chuẩn hóa payload từ RabbitMQ message
const raw = $input.first().json;
let payload = {};

if (raw.content) {
  if (typeof raw.content === 'string') {
    try {
      payload = JSON.parse(raw.content);
    } catch (e) {
      payload = { text: raw.content };
    }
  } else if (typeof raw.content === 'object') {
    payload = raw.content;
  }
} else {
  payload = raw;
}

// 2. Xác định eventType và leadId
const eventType = payload.eventType || raw.eventType || raw.fields?.routingKey || 'unknown';
const data = payload.data || payload;
const leadId = data.leadId || payload.leadId || null;

// 3. Kiểm tra tính hợp lệ của sự kiện
const isLeadCreated = eventType === 'lead.created' || (!payload.eventType && !!leadId);
const isValid = Boolean(leadId && isLeadCreated);

return [{
  json: {
    eventId: payload.eventId || 'evt-' + Date.now(),
    eventType,
    leadId,
    isValid,
    receivedAt: new Date().toISOString(),
    rawPayload: payload
  }
}];

const meta = $('⚙️ Normalize Event Payload').first().json;

return [{
  json: {
    auditStatus: 'EVENT_SKIPPED_SAFELY',
    eventId: meta.eventId,
    receivedEventType: meta.eventType,
    leadId: meta.leadId || 'N/A',
    reason: meta.leadId ? `Event type '${meta.eventType}' does not trigger Lead Intake (expected 'lead.created')` : 'Payload missing leadId identifier.',
    actionTaken: 'Safely acknowledged and dropped without processing',
    loggedAt: new Date().toISOString()
  }
}];

const lead = $input.first().json;
const meta = $('⚙️ Normalize Event Payload').first().json;

// Kiểm tra trạng thái và owner hiện tại của Lead
const hasOwner = Boolean(lead.ownerId || (lead.owner && lead.owner.id));
const isEligible = lead.status === 'NEW' || !lead.status;
const needsAssignment = isEligible && !hasOwner;

return [{
  json: {
    leadId: lead.id,
    status: lead.status || 'NEW',
    currentOwnerId: lead.ownerId || (lead.owner ? lead.owner.id : null),
    currentOwnerName: lead.owner ? lead.owner.name : null,
    hasOwner,
    isEligible,
    needsAssignment,
    leadSnapshot: {
      firstName: lead.firstName,
      lastName: lead.lastName,
      email: lead.email,
      companyName: lead.companyName,
      sourceId: lead.sourceId
    },
    inspectedAt: new Date().toISOString()
  }
}];

// Chọn Sales Owner phù hợp dựa trên danh sách users từ Backend
const usersRes = $input.first().json;
const inspect = $('🔎 Inspect Status & Ownership').first().json;

const users = Array.isArray(usersRes) ? usersRes : (usersRes.data || []);
// Ưu tiên người dùng có role = 'SALES' và status = 'ACTIVE'
const activeSales = users.filter(u => u.role === 'SALES' && u.status === 'ACTIVE');

let selectedUser = null;
let assignReason = '';

if (activeSales.length > 0) {
  // Round-robin phân bổ dựa trên hash ID của Lead để đảm bảo cân bằng và idempotent
  const hash = inspect.leadId.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
  selectedUser = activeSales[hash % activeSales.length];
  assignReason = 'Assigned to active sales representative via automated round-robin';
} else if (users.length > 0) {
  // Fallback: Gán cho bất kỳ user nào đang active
  selectedUser = users.find(u => u.status === 'ACTIVE') || users[0];
  assignReason = 'Fallback assignment to default workspace member (no active sales rep found)';
} else {
  assignReason = 'No users available in workspace';
}

return [{
  json: {
    leadId: inspect.leadId,
    hasOwner: false,
    newOwnerId: selectedUser ? selectedUser.id : null,
    newOwnerName: selectedUser ? selectedUser.name : 'Unassigned',
    newOwnerEmail: selectedUser ? selectedUser.email : null,
    assignmentReason: assignReason,
    canAssign: Boolean(selectedUser && selectedUser.id)
  }
}];

// Nhánh giữ nguyên Owner đã có: không thay đổi owner tùy tiện (Step 9)
const inspect = $('🔎 Inspect Status & Ownership').first().json;

return [{
  json: {
    leadId: inspect.leadId,
    hasOwner: true,
    retainedOwnerId: inspect.currentOwnerId,
    retainedOwnerName: inspect.currentOwnerName || 'Existing Owner',
    assignmentReason: 'Existing owner retained without modification',
    canAssign: false
  }
}];

// Gom 2 luồng (vừa gán mới hoặc giữ nguyên owner) trước khi chuyển sang Post-Processing
let leadId = null;
let ownerId = null;
let ownerName = null;
let actionTaken = '';

try {
  const patchNode = $('✏️ Update Lead Owner').first();
  if (patchNode) {
    const resolved = $('🎯 Resolve Sales Assignee').first().json;
    leadId = resolved.leadId;
    ownerId = resolved.newOwnerId;
    ownerName = resolved.newOwnerName;
    actionTaken = 'OWNER_ASSIGNED';
  }
} catch (e) {}

if (!leadId) {
  try {
    const retainedNode = $('🛡️ Retain Existing Owner').first().json;
    leadId = retainedNode.leadId;
    ownerId = retainedNode.retainedOwnerId;
    ownerName = retainedNode.retainedOwnerName;
    actionTaken = 'OWNER_RETAINED';
  } catch (e) {}
}

return [{
  json: {
    leadId,
    ownerId,
    ownerName,
    actionTaken,
    readyForQualification: Boolean(leadId),
    timestamp: new Date().toISOString()
  }
}];

const prep = $('🔄 Prepare Post-Processing').first().json;
const qualifyRes = $input.first().json;

const qualificationTriggered = !qualifyRes.error && (qualifyRes.statusCode ? qualifyRes.statusCode < 400 : true);

return [{
  json: {
    auditStatus: 'LEAD_INTAKE_SUCCESS',
    leadId: prep.leadId,
    ownerId: prep.ownerId,
    ownerName: prep.ownerName,
    ownerAction: prep.actionTaken,
    qualificationPipelineTriggered: qualificationTriggered,
    backendResponse: qualifyRes,
    completedAt: new Date().toISOString()
  }
}];

const errorData = $input.first().json;

return [{
  json: {
    auditStatus: 'LEAD_INTAKE_FAILED',
    errorMessage: errorData.execution?.error?.message || errorData.message || 'Workflow execution error',
    context: errorData.execution?.error?.context || null,
    failedAt: new Date().toISOString()
  }
}];
